class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        int left = 0, right = n - 1, p = n - 1;
        while (left <= right) {
            int lVal = nums[left] * nums[left];
            int rVal = nums[right] * nums[right];
            if (lVal > rVal) {
                res[p--] = lVal;
                left++;
            } else {
                res[p--] = rVal;
                right--;
            }
        }
        return res;
    }
}

