// For i from 0 to n-1:
//   Remove elements out of window: while (!deque.isEmpty() && deque.peekFirst() <= i - k) deque.pollFirst()
//   Remove smaller elements: while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) deque.pollLast()
