// 2. sign = 1; if s[i] == '-' (sign = -1, i++) else if s[i] == '+' (i++)
// 3. while i < n and isDigit(s[i]):
//      if total > MAX/10 or (total == MAX/10 and digit > 7):
//          return sign == 1 ? MAX : MIN
//      total = total * 10 + digit; i++
// 4. return total * sign

