class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int left = 1;
        int right = 0;
        for (int p : piles) right = Math.max(right, p);

        int bestSpeed = right;
        while (left <= right) {
            int midSpeed = left + (right - left) / 2;
            if (canFinish(piles, midSpeed, h)) {
                bestSpeed = midSpeed;
                right = midSpeed - 1; // Seek smaller valid speed
            } else {
                left = midSpeed + 1;  // Need faster speed
            }
        }
        return bestSpeed;
    }

    private boolean canFinish(int[] piles, int speed, int maxHours) {
        long totalHours = 0;
        for (int p : piles) {
            totalHours += (p + speed - 1) / speed; // Ceiling division
        }
        return totalHours <= maxHours;
    }
}

class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int left = 0, right = 0;
        for (int w : weights) {
            left = Math.max(left, w);
            right += w;
        }

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canShip(weights, mid, days)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private boolean canShip(int[] weights, int capacity, int maxDays) {
        int daysNeeded = 1;
        int currentWeight = 0;

        for (int w : weights) {
            if (currentWeight + w > capacity) {
                daysNeeded++;
                currentWeight = 0;
            }
            currentWeight += w;
        }
        return daysNeeded <= maxDays;
    }
}

class Solution {
    public int splitArray(int[] nums, int k) {
        int left = 0, right = 0;
        for (int num : nums) {
            left = Math.max(left, num);
            right += num;
        }

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canSplit(nums, mid, k)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private boolean canSplit(int[] nums, int maxSum, int maxSubarrays) {
        int count = 1;
        int currentSum = 0;

        for (int num : nums) {
            if (currentSum + num > maxSum) {
                count++;
                currentSum = num;
            } else {
                currentSum += num;
            }
        }
        return count <= maxSubarrays;
    }
}

