        if (x < 2) return x;
        int l = 1, r = x / 2, ans = 1;
        while (l <= r) {
            int m = l + (r - l) / 2;
            if (m <= x / m) {
                ans = m;
                l = m + 1;
            } else {
                r = m - 1;
